	private static Map<List<Value>, Long> expected(int repeats, long limit) {
		Map<List<Value>, Long> result = new LinkedHashMap<>();
		long emitted = 0L;
		for (long subject = 2L; subject <= KEYS; subject++) {
			for (int city = 0; city < repeats; city++) {
				for (int friend = 0; friend < FANOUT; friend++) {
					if (limit >= 0L && emitted == limit) {
						return result;
					}
					result.merge(List.of(value(1_001L + city), value(2_001L + subject * FANOUT + friend)),
							1L, Long::sum);
					emitted++;
				}
			}
		}
		return result;
	}

	private static Value value(long id) {
		return SimpleValueFactory.getInstance().createIRI("urn:factorized-enum:" + id);
	}

	private record Measured(Map<List<Value>, Long> bag, Map<Long, Integer> opensByKey, int prefixOpens,
			int branchOpens, int closed, int prefixRows, int branchRows, LmdbNativeDecisionTestAccess.Captured quote) {
	}

