	/** Exact raw records: one missing key and three successful keys, each encountered once or three times. */
	private static final class CountingSource implements NativeLmdbQuerySource {
		final List<long[]> data = new ArrayList<>();
		final Map<Long, Integer> opensByKey = new LinkedHashMap<>();
		int prefixOpens, branchOpens, closed, prefixRows, branchRows;

		CountingSource(int repeats) {
			for (long subject = 1L; subject <= KEYS; subject++) {
				for (int city = 0; city < repeats; city++) {
					data.add(new long[] { subject, CITY, 1_001L + city, 0L });
				}
				if (subject > 1L) {
					for (int friend = 0; friend < FANOUT; friend++) {
						data.add(new long[] { subject, KNOWS, 2_001L + subject * FANOUT + friend, 0L });
					}
				}
			}
		}

		@Override
		public Object idSpace() {
			return this;
		}

		@Override
		public boolean hasStatementsInSource() {
			return true;
		}

		@Override
		public long idOf(Value value) {
			String prefix = "urn:factorized-enum:";
			return value.stringValue().startsWith(prefix)
					? Long.parseLong(value.stringValue().substring(prefix.length()))
					: UNKNOWN_ID;
		}

		@Override
		public Value lazyValue(long id) {
			return value(id);
		}

		@Override
		public IndexAccessProfile indexAccessProfile() {
			return coveringProfile(data.size());
		}

		@Override
		public OptionalDouble meanFanOut(long predicate, boolean bySubject) {
			long count = data.stream().filter(quad -> quad[1] == predicate).count();
			long keys = keys(predicate, bySubject);
			return OptionalDouble.of(keys == 0L ? 0D : (double) count / keys);
		}

		@Override
		public OptionalDouble distinctFanOutKeys(long predicate, boolean bySubject) {
			return OptionalDouble.of(keys(predicate, bySubject));
		}

		@Override
		public OptionalLong adjacencyKeyDomainCardinality(long predicate, boolean bySubject) {
			return OptionalLong.of(keys(predicate, bySubject));
		}

		long keys(long predicate, boolean bySubject) {
			return data.stream()
					.filter(quad -> quad[1] == predicate)
					.mapToLong(quad -> quad[bySubject ? 0 : 2])
					.distinct()
					.count();
		}

		List<long[]> matches(long s, long p, long o, long c) {
			return data.stream()
					.filter(q -> (s == UNKNOWN_ID || s == q[0]) && (p == UNKNOWN_ID || p == q[1])
							&& (o == UNKNOWN_ID || o == q[2]) && (c == UNKNOWN_ID || c == q[3]))
					.toList();
		}

		@Override
		public RecordIterator statements(long s, long p, long o, long c) {
			if (p == CITY) {
				prefixOpens++;
			}
			if (p == KNOWS) {
				branchOpens++;
				opensByKey.merge(s, 1, Integer::sum);
			}
			List<long[]> records = matches(s, p, o, c);
			return new RecordIterator() {
				int at;
				boolean done;

				@Override
				public long[] next() {
					if (at == records.size()) {
						return null;
					}
					if (p == CITY) {
						prefixRows++;
					}
					if (p == KNOWS) {
						branchRows++;
					}
					return records.get(at++);
				}

				@Override
				public void close() {
					if (!done) {
						done = true;
						closed++;
					}
				}
			};
		}

		@Override
		public long count(long s, long p, long o, long c) {
			return matches(s, p, o, c).size();
		}

		@Override
		public boolean has(long s, long p, long o, long c) {
			return !matches(s, p, o, c).isEmpty();
		}

		@Override
		public double estimate(long s, long p, long o, long c) {
			return count(s, p, o, c);
		}
	}
